insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('de53a5d6-e715-51ef-b590-83d7fb459508', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'As used in the text, what does the word “constantly” most nearly mean?', '["Nonstop", "Quickly", "Fearfully", "Enough"]'::jsonb, 1, 'The following text is adapted from Willa Cather’s 1912 novel Alexander’s Bridge.
For the next few days Alexander was very busy. He took a desk in the office of a [Scottish] engineering firm on Henrietta Street, and was at work almost <u>constantly</u>. He avoided the clubs and usually dined alone at his hotel.'),
  ('568aeda2-9715-533f-b907-0aa07328e737', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice completes the text with the most logical and precise word or phrase?', '["compensated for", "clashed with", "coincided with", "developed into"]'::jsonb, 2, 'Radiocarbon dating can help scientists determine whether the extinction of the long-nosed peccary around 9000 BCE _____ the arrival of humans in the same region of the Americas. If instead the long-nosed peccary died out before humans could have altered its habitat, that suggests that its extinction was the result of some other factor, such as climate change.'),
  ('4884240d-d940-5c81-8185-1a4f11b5c24b', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice completes the text with the most logical and precise word or phrase?', '["incentives for", "calibrations with", "developments of", "fluctuations in"]'::jsonb, 3, 'Economists often assert that countries looking to increase their reliance on solar energy should expand their capacity for storage; having an ample reserve of stored energy can mitigate the effects of _____ solar energy collection caused by unpredictable shifts in cloud cover and haze.'),
  ('1c122486-7c67-5a9e-bb78-21e635094f5b', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice completes the text with the most logical and precise word or phrase?', '["reverence", "candor", "prudence", "curiosity"]'::jsonb, 4, 'In the United States, historians of the American Revolution once had a tendency to approach their subject with _______: they had so much admiration for the people who carried out the revolution that they were far from objective in their scholarship.'),
  ('49d9a115-759e-5636-af6e-18af4f8c7721', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice best describes the overall structure of the text?', '["It names animal species found in a place, then names plant species there.", "It sketches a setting by presenting a series of images of nature.", "It identifies a location, then refers to a person living there.", "It makes an extended comparison of nature to human emotions."]'::jsonb, 5, 'The following text is adapted from the 1895 poem “Marshlands” by Emily Pauline Johnson, a Kanienkahagen (Mohawk) writer also known as Tekahionwake.

Among the wild rice in the still lagoon,
In monotone the lizard shrills his tune.
The wild goose, homing, seeks a sheltering,
Where rushes grow, and oozing lichens cling.
Late cranes with heavy wing, and lazy flight,
Sail up the silence with the nearing night.
And like a spirit, swathed in some soft veil.
Steals twilight and its shadows o''er the swale.
Hushed lie the sedges, and the vapours creep,
Thick, grey and humid, while the marshes sleep.'),
  ('f0ecf3dc-5dd0-5c86-90b6-a1fb16eb5cf8', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice best states the main purpose of the text?', '["It assesses a historical figure’s significance by considering both his achievements and failings.", "It explains how a historical figure’s reputation has improved significantly with the passage of time.", "It argues that the seeming prominence of a historical figure is largely due to the actions of others.", "It catalogs the most notable achievements of a historical figure."]'::jsonb, 6, 'President Richard Nixon is most famous for his participation in the 1970s Watergate political scandal, a convoluted tale of criminality and eroded ethics involving a constellation of associates such as Chief of Staff H.R. “Bob” Haldeman and Secretary of State Henry Kissinger. But Nixon’s legacy is complex: he has been praised for his role in creating the Environmental Protection Agency, and he once made an attempt at reforming United States health care policy that is arguably a precursor to the Affordable Care Act, which became law during the Barack Obama administration.'),
  ('b7ada72b-472a-554b-a7e2-07bc58ccdae8', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice best states the main purpose of the text?', '["It suggests that there are possible flaws in ohmic heating technologies that have not yet been well researched.", "It introduces ohmic heating as a food preservation technology and identifies one of its advantages.", "It provides an overview of the research into ohmic heating both globally and in a specific country.", "It explains why conventional heating methods are popular in commercial applications and proposes a shift away from these methods."]'::jsonb, 7, 'Thermal technologies have been used in the food industry for over 100 years, providing a way of preserving food in large batches. Recent advancements in ohmic heating were made through research in Brazil on the preservation of acerola pulp. Ohmic heating is generally considered to be an improvement over more conventional thermal preservation methods: whereas conventional methods transfer energy from the surface of a food to its interior, ohmic heating passes electric current through food products to generate heat within the food itself.'),
  ('889c2356-58c9-5f19-99aa-d8c2e699a24e', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice best describes the function of the reference to the “wooing kestrel” (a type of bird) in the text as a whole?', '["It suggests that there are some aspects of nature that will forever be mysterious to humans.", "It emphasizes the speaker’s belief that her friend is not sharing his true feelings with her.", "It presents the natural world as aligning with the experience of the speaker and her friend.", "It illustrates the assertion that the definition of peace changes from person to person."]'::jsonb, 8, 'The following text is adapted from Anne Spencer’s 1922 poem "Translation."
We trekked into a far country,
My friend and I.
Our deeper content was never spoken.
But each knew all the other said.
He told me how calm his soul was laid
By the lack of anvil and strife.
"The wooing kestrel," I said, "mutes his mating-note
To please the harmony of this sweet silence."'),
  ('3829338d-187a-5b52-a282-638e232b41ef', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Based on the text, what most likely motivates Tia Ana’s behavior during Salomé’s salon?', '["She finds the guests to be dull and is eager to find a way to leave the salon.", "She is eager to tell the guests about the new school she is opening and anticipates their approval of her plans.", "She is anxious for the gathering to disperse so that she can ready the space for her own needs.", "She is frustrated because she needs assistance elsewhere in the house, but Salomé is unavailable while entertaining the guests."]'::jsonb, 9, 'The following text is adapted from Julia Alvarez’s 2000 novel In the Name of Salomé. Salomé, a poet, is hosting guests in the front parlor of her family home, and Ramona is her sister. A salon is a social gathering for the exploration of intellectual ideas.
It was evening when the two men got up to leave. Tia Ana had already come into the room several times to see if these guests had departed yet. The front parlor had always been her special province, as she used it for her little school. Now, every evening, it turned into Salomé’s salon, as Ramona called it, and it was never in order for its transformation back to a classroom the following morning.

©2000 by Julia Alvarez'),
  ('14e975ef-c7be-5546-86cc-810c4aaf0f9c', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice best states the main idea of the text?', '["Villasana began her artistic career by painting portraits of famous people and then transitioned to depicting everyday people instead.", "Villasana’s works focus on recognizing both famous and everyday examples of human strength and connection.", "Villasana’s portrayal of a woman making tortillas focuses more on human connection than it does on human resilience.", "Villasana’s depiction of boxer Muhammad Ali receives more attention from scholars than her depiction of a woman making tortillas does."]'::jsonb, 10, 'Mexican textile artist Victoria Villasana weaves stories of triumph, using her unique method of applying colorful yarn to photographs of people. In some works, Villasana focuses on celebrating cultural icons who are people of color, as she does in her depiction of boxer Muhammad Ali. However, in other works, Villasana honors ordinary people, as she does in her captivating portrayal of a woman making tortillas. Villasana sees both of these approaches as ways of depicting the power and interconnectedness of all people.'),
  ('2126c2d2-b9bf-592c-aa81-677c9b810160', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice most effectively uses data from the table to complete the comparison?', '["47.3 square miles.", "32.4 square miles", "77.1 square miles.", "595.7 square miles."]'::jsonb, 11, '**Total Areas of Five Pueblo Nations in New Mexico**

| Tribal nation | Area (square miles) |
| Santo Domingo Pueblo | 106.3 |
| Pueblo de San Ildefonso | 47.3 |
| Nambe Pueblo | 32.4 |
| Santa Clara Pueblo | 77.1 |
| Pueblo of Acoma | 595.7 |

There are nineteen Pueblo tribal nations in New Mexico. A student in a geography class is a citizen of Santo Domingo Pueblo in the north-central part of the state. The student wants to compare the total area covered by Santo Domingo Pueblo with the total areas of various other Pueblo nations in the state. Looking at the table, the student finds that the total area of Santo Domingo Pueblo is 106.3 square miles, while the total area of Nambé Pueblo is ______'),
  ('4abb90cd-e25b-56b6-ace5-37c33c40efac', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice best describes data from the graph that support the researcher’s claim?', '["Spirit Lake had approximately 100 days of ice in the winter of 1980-81 and approximately 125 days of ice in the winter of 2005-06.", "Lake Kallavesi had approximately 175 days of ice in the winter of 1980-81 and approximately 145 days of ice in the winter of 2005-06.", "The highest number of days of ice a lake in the graph had in the winter of 2005-06 was approximately 145.", "None of the three lakes had fewer days of ice in the winter of 1980-81 than they did in the winter of 2005-06."]'::jsonb, 12, '![figure](/q/mar24/001.webp)

It is common for freshwater lakes near or above a latitude of 45° north of the equator, like Lake Stechlin in Germany, to accumulate surface ice in winter. The amount and duration of ice depends on many factors, including local weather conditions as well as the lake’s depth, volume, and surface area, but a climate researcher claims that some lakes in these latitudes have seen a decline in the duration of ice between the early 1980s and the mid-2000s.'),
  ('b5c7c9fe-ca45-518d-833c-cc958a36a3dd', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice best describes data from the table that support the journalist’s claim?', '["Cinema Paradiso was recognized by the Oscars, but Instructions Not Included, which was not recognized by the Oscars, had higher lifetime earnings.", "La Cage aux Folles, which was recognized by the Oscars, earned less money in its opening weekend but had higher lifetime earnings than Padmaavat, which was not recognized by the Oscars.", "Although La Cage aux Folles and Cinema Paradiso were both recognized by the Oscars, La Cage aux Folles had higher lifetime and opening weekend earnings.", "Although the opening weekend earnings were \\$7.846.426 for Instructions Not Included and \\$4.493.384 for Padmaavat, neither film was recognized by the Oscars."]'::jsonb, 13, '**Highest-Grossing Films in a Language Other than English at US Box Office**

| Title | Lifetime gross earnings | Opening weekend box office gross earnings | US release date | Director | Oscar Nominated? |
| Cinema Paradiso | \$11,990,401 | \$16,552 | February 2, 1990 | Giuseppe Tornatore | Yes |
| La Cage aux Folles | \$20,424,259 | \$18,709 | March 30, 1979 | Edouard Molinaro | Yes |
| Instructions Not Included | \$44,467,206 | \$7,846,426 | August 30, 2013 | Eugenio Derbez | No |
| Padmaavat | \$11,846,060 | \$4,493,384 | January 25, 2018 | Sanjay Leela Bhansali | No |

Many films in a language other than English grow to be financially successful over the course of their time in movie theaters in the United States, but some become immediate successes in their opening weekends. A journalist claims that a film’s reception can greatly influence its long-term success. Indications that the film is of high quality, such as an Oscar nomination, can dramatically boost public interest in the film and thus its overall earnings, even with a relatively modest opening weekend performance.'),
  ('5a737f5e-6aae-5030-b7f6-ee48390d25f7', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which quotation from a survey respondent would best illustrate the students'' claim?', '["“People behind this idea hardly consulted any of us who work or live around Cuba Street. This proposal doesn’t reflect our opinions.”", "“A lot of the businesses on Cuba Street depend on foot traffic. If fewer people walk on the street because there are more cars, those businesses might struggle.”", "“Cuba Street is one of the most unusual streets in Wellington. I would hate to see it become just like any other street.”", "“I think Wellington needs more streets like Cuba Street, not more streets full of loud cars spewing exhaust fumes into the air.”"]'::jsonb, 14, 'Cuba Street in Wellington, New Zealand, is a pedestrianized street—it is closed to car traffic except in special circumstances. Students in Wellington surveyed residents about a proposal to increase the amount of car traffic allowed on Cuba Street. The survey results suggest that residents are generally against the proposal, and the students claim that much of the survey respondents'' opposition stems from concerns that allowing more car traffic would diminish the distinctive character of the street.'),
  ('d52f645a-d287-5a93-ab47-31cb92b79bde', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice most logically completes the text?', '["Geoffrey of Monmouth’s accounts of Arthurian legends in his History are more similar overall in content to the accounts in Tom a Lincoln than they are to the accounts in Roman de Brut.", "Geoffrey of Monmouth was unaware of stories of the Round Table when composing his History, though historians know that works containing such stories were available to him.", "any Arthurian legend that mentions the Round Table likely has a lineage that connects it to Roman de Brut.", "Roman de Brut is more historically accurate than History, because Tom a Lincoln had not been written when Geoffrey of Monmouth was writing his History."]'::jsonb, 15, 'Arthurian legends (tales related to the character of King Arthur) derive from many sources, such as Pa gur yv y porthaur, composed in the 10th century, and Tom a Lincoln from around 1607. One of the most significant sources, Geoffrey of Monmouth’s History of the Kings of Britain, was written in the 1130s; some material from it was later adapted by the Norman poet Wace into the Roman de Brut in 1155. But while the Roman de Brut includes references to the famous Round Table at which Arthur’s knights assembled, nothing written before 1155 does, which suggests that _____'),
  ('c3995be2-43ba-51c4-92d5-7fe14a79c5e2', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["libraries: train", "libraries train", "libraries—train", "libraries, train"]'::jsonb, 16, 'Azulejos, mosaics made of glazed ceramic tiles, can be found throughout Portugal. These mosaics beautify places such as _____ stations, and public squares.'),
  ('9d582a34-8434-5e85-a3c9-93aed1ee0cae', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Gothic—", "Gothic;", "Gothic", "Gothic,"]'::jsonb, 17, 'Writer Silvia Moreno-Garcia’s love of short fiction began when she read a collection of Edgar Allan Poe stories as a child, and she would develop into a prolific short story writer herself, publishing pieces like “In the Details” (2015) and “Shade of the Ceiba Tree” (2011). Yet she’s become, with the breakout success of her 2020 novel Mexican ______ best known as a novelist.'),
  ('b3e1710d-126b-5c8c-997b-caff21f71e04', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["1950s", "1950s, and", "1950s,", "1950s and"]'::jsonb, 18, 'Featuring works by the photographers Madame d’Ora and Charlotte Rudolph, the 2021 exhibition The New Woman Behind the Camera set out to provide a wide-ranging overview of photography by women in the 1920s through the ______ given the collection’s breadth of more than 120 photos, its efforts were largely successful.'),
  ('6f6ed300-4888-57ce-9878-888185785ed2', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["was", "were", "has been", "is"]'::jsonb, 19, 'Myra Musselmann-Carr and Lily Everett were among the 300 artists who exhibited at the 1913 Armory Show, a groundbreaking New York City art exhibition that introduced modernism to American audiences. Though now canonical, many works featured in the show—particularly one abstract cubist painting by Marcel Duchamp—_______ considered shocking at the time.'),
  ('f02b456c-2c81-5fab-ac2c-ae3f72ddcab5', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["painting Uprising,", "painting Uprising", "painting, Uprising", "painting. Uprising."]'::jsonb, 20, 'Along the hallowed walls of New York City’s Museum of Modern Art hangs 41.1-by-37.6-inch oil _____ which was created in 1910 by American artist Lyonel Feininger.'),
  ('16399b4b-d34b-5171-83eb-0d7ba3260bd4', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["would be honored", "is honored", "will be honored", "had been honored"]'::jsonb, 21, 'In 1987, chemist Ahmed Zewail devised a novel technique in optical spectroscopy that allowed him to study ultrafast chemical reactions occurring within molecules. Years later, he _____ for this groundbreaking research with the Robert A. Welch Award and the Priestley Medal from the American Chemical Society and hence would become known as the father of femtochemistry.'),
  ('fa17a2a0-0a43-5157-9cc0-502451db46fe', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice completes the text with the most logical transition?', '["Similarly,", "In other words,", "As a result,", "In conclusion,"]'::jsonb, 22, 'Humans inherit specific physical traits (like having brown or green eyes) from their parents. _____ dogs inherit specific physical traits (like having long or short tails) from their parents.'),
  ('9194a8aa-63cd-5d69-bad9-f2c11f2954f9', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice completes the text with the most logical transition?', '["Alternatively,", "Accordingly,", "Nevertheless,", "At that time,"]'::jsonb, 23, 'Author Ursula K. Le Guin’s Planet of Exile is a science fiction story set in an era of intergalactic travel, whereas her The Tombs of Atuan is a work of fantasy set in a land of heroes and dragons. ______ both fans of science fiction and fans of fantasy are among her many readers.'),
  ('4ab30b05-3133-5dc4-9c52-072c2fa55f08', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'The student wants to emphasize a similarity between kale and carrots. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Carrots are vegetables that contain ascorbic acid; in fact, there is 6 mg of it in every 100g of carrot.", "Humans cannot make vitamin C in their bodies, so they must get this essential nutrient from vegetables, such as kale.", "One thing that kale and carrots have in common is that they both contain vitamin C.", "Just like fruits, vegetables are a food that humans can eat to get ascorbic acid, also known as vitamin C."]'::jsonb, 24, 'While researching a topic, a student has taken the following notes:

Kale is a vegetable that contains ascorbic acid, an essential nutrient for humans.
There is 120 milligrams (mg) of ascorbic acid in every 100 grams (g) of kale.
Carrots are vegetables that contain ascorbic acid.
There is 6 mg of ascorbic acid in every 100 g of carrot.
Humans cannot make ascorbic acid in their bodies, so they must get it from foods, including fruits and vegetables.
Ascorbic acid is also known as vitamin C.'),
  ('4c9a02a1-fb41-5a38-a2fb-c9a1a5e84318', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'The student wants to explain why brine pools are toxic to most sea life. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The water in brine pools is toxic to most sea life because it is three to eight times saltier than the surrounding ocean.", "The brine pools in the Gulf of Aqaba are toxic to most sea life and were discovered by researchers in 2022.", "Though brine pools are toxic to most sea life, some bacteria can survive there.", "Brine pools are salty underwater lakes that sit on the ocean floor."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

In 2022, University of Miami researchers discovered brine pools in the Gulf of Aqaba.
A brine pool is an underwater lake that sits on the ocean floor.
The water in brine pools is three to eight times saltier than the surrounding ocean.
The extreme saltiness of this water makes it toxic to most sea life.
Some forms of bacteria are able to survive in brine pools.'),
  ('fd178eff-cb94-5a72-80b4-0332f7ed39e6', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'The student wants to specify where Discoglossus nigriventer was identified. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["In 2015, a living specimen of Dysphania pusilla was found in New Zealand.", "Previously believed to be extinct, a living specimen of Discoglossus nigriventer was identified in Israel.", "Examples of Lazarus species can be found in Discoglossus nigriventer as well as Dysphania pusilla.", "A living specimen of Discoglossus nigriventer, once believed to be extinct, was identified in 2011."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

Discoglossus nigriventer is an amphibian species.
It was believed to be extinct until a living specimen was identified in Israel in 2011.
Dysphania pusilla is a plant species.
It was believed to be extinct until a living specimen was identified in New Zealand in 2015. They are considered Lazarus species.
"Lazarus species" is a term for living species of organisms that were once believed to be extinct.'),
  ('2e9f8ac8-e0d6-585f-9f7e-d392e87cc586', '47e4240e-e5f4-5ffb-8003-498bdcb98228', 'Which choice most effectively uses information from the given sentences to emphasize a similarity between Morris and Snethlage?', '["The entomologist Margarett a Morris was born in 1797, but ornithologist Emilie Snethlage was born later, in 1868.", "Like entomologist Margarett a Morris, ornithologist Emilie Snethlage dedicated her scientific career to the study of living organisms.", "Entomology and ornithology are just two examples of the myria d fields in which scientists can specialize.", "Margarett a Morris conducted research on wheat flies and cicadas;Emilie Snethlage, by contrast, is known for her research on Brazilian birds."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Entomology is primarily the study of insects.
Margaretta Morris was an American entomologist born in 1797.
She is known for her research on wheat flies and cicadas.
Ornithology is primarily the study of birds.
Emilie Snethlage was a German-Brazilian ornithologist born in 1868.
She is known for her research on Brazilian birds.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('de53a5d6-e715-51ef-b590-83d7fb459508', 0, null, '**Choice A is correct.** In the sentence "was at work almost constantly," the adverb describes how frequently Alexander was working; "constantly" means continuously or without stopping, so "nonstop" best matches the passage’s sense that he was at work nearly all the time.
**Choice B is incorrect.** "Quickly" refers to speed, not duration or frequency; the passage emphasizes how often he worked, not how fast he worked.
**Choice C is incorrect.** "Fearfully" conveys emotion (fear), which is unrelated to the context describing Alexander’s work habits.
**Choice D is incorrect.** "Enough" indicates sufficiency and does not capture the idea of uninterrupted or very frequent activity conveyed by "constantly."
**Faster approach:** Substitute each choice into the sentence mentally; the one that preserves the original meaning (here, uninterrupted/very frequent activity) is correct—eliminate options that change meaning (speed, emotion, sufficiency).'),
  ('568aeda2-9715-533f-b907-0aa07328e737', 2, null, '**Choice C is correct.** The sentence contrasts two timing possibilities: that the extinction happened at the same time as humans arrived (which would implicate humans) versus that the peccary died out before humans could have altered its habitat. "Coincided with" precisely means "occurred at the same time as," matching the contrast and making the conditional logic of the next sentence coherent.
**Choice A is incorrect.** "Compensated for" means to make up for something, which makes no sense in referring to the timing relationship between an extinction and human arrival.
**Choice B is incorrect.** "Clashed with" implies a conflict or opposition, not a temporal relationship; it doesn’t express whether the events were simultaneous.
**Choice D is incorrect.** "Developed into" indicates transformation or evolution over time, not coincidence in timing, so it fails to express the intended contrast.
**Faster approach:** Substitute a plain phrase like "happened at the same time as" into the sentence; choose the answer that matches that temporal meaning (i.e., "coincided with").'),
  ('4884240d-d940-5c81-8185-1a4f11b5c24b', 3, null, '**Choice D is correct.** The sentence calls for a noun phrase describing varying amounts of collected solar energy; "fluctuations in solar energy collection" precisely names variability that storage would mitigate, and it fits grammatically and logically with the cause given ("unpredictable shifts in cloud cover and haze").
**Choice A is incorrect.** "Incentives for solar energy collection" would mean policy or financial encouragement, which is not what storage mitigates and does not match the described cause of variability.
**Choice B is incorrect.** "Calibrations with solar energy collection" is awkward and nonsensical here: calibrations are adjustments, not effects caused by cloud cover and haze.
**Choice C is incorrect.** "Developments of solar energy collection" suggests progress or growth, not the short-term variability that storage would smooth out, so it doesn’t match the context.
**Faster approach:** Look for a phrase that names variability or instability to pair with "mitigate the effects of"; eliminate choices that imply policy, progress, or awkward constructions and choose the one meaning variation ("fluctuations in").'),
  ('1c122486-7c67-5a9e-bb78-21e635094f5b', 0, null, '**Choice A is correct.** The sentence says historians "had so much admiration for the people who carried out the revolution that they were far from objective," so a word meaning deep respect or veneration —"reverence" — precisely captures that admiration and explains the lack of objectivity.
**Choice B is incorrect.** "Candor" means frankness or openness; it does not convey admiration and would not explain why historians lacked objectivity.
**Choice C is incorrect.** "Prudence" means caution or carefulness, which is unrelated to having admiration or to being biased by admiration.
**Choice D is incorrect.** "Curiosity" means interest or inquisitiveness; while it involves attention, it does not imply the admiring attitude described and so cannot account for lack of objectivity.
**Faster approach:** Match the blank to the clause explaining lack of objectivity—choose the option that denotes admiration or veneration (here, "reverence").'),
  ('49d9a115-759e-5636-af6e-18af4f8c7721', 1, null, '**Choice B is correct.** The poem creates a clear setting by presenting a sequence of sensory images — sounds ("the lizard shrills his tune"), bird movements ("The wild goose... seeks a sheltering," "Late cranes with heavy wing"), plant life ("rushes," "sedges"), and atmospheric detail ("twilight and its shadows," "vapours creep"). Together these images sketch the marshland scene rather than developing an argument or narrative about people.
**Choice A is incorrect.** The lines mix animals, plants, and atmosphere rather than first naming animals then plants in a rigid order; the structure is image-driven, not a list segregated by category.
**Choice C is incorrect.** The poem locates a natural place but does not introduce or discuss a person living there.
**Choice D is incorrect.** While evocative, the poem does not develop an extended comparison of nature to human emotions; it focuses on descriptive imagery of the marsh itself.
**Faster approach:** Scan for the dominant technique — if a passage strings sensory details and concrete images to set a scene, choose the option about sketching a setting or imagery; eliminate choices that assert argument, comparison, or character development.'),
  ('f0ecf3dc-5dd0-5c86-90b6-a1fb16eb5cf8', 0, null, '**Choice A is correct.** The passage presents both negative and positive aspects of Nixon’s legacy—his central role in the Watergate scandal and his praised accomplishments (creating the EPA and proposing health-care reform). By giving both achievements and failings, the passage assesses his significance in a balanced way, which matches Choice A.
**Choice B is incorrect.** The passage does not claim Nixon’s reputation has improved significantly over time; it only notes complexity and that one of his reforms could be seen as a precursor to later legislation, not an overall rehabilitation of reputation.
**Choice C is incorrect.** The passage does not argue that Nixon’s prominence is mainly due to others’ actions; it attributes major actions and controversies directly to Nixon himself.
**Choice D is incorrect.** The passage mentions notable achievements but also emphasizes failings (Watergate), so it is not merely a catalog of achievements.
**Faster approach:** Look for language that presents contrasting details; if the passage lists both positive and negative points about the subject, the main purpose is balance/assessment (Choice A).'),
  ('b7ada72b-472a-554b-a7e2-07bc58ccdae8', 1, null, '**Choice B is correct.** The passage introduces ohmic heating as a preservation technology and highlights an advantage: it generates heat within food by passing electric current, unlike conventional methods that transfer energy from the surface inward. The first sentence establishes the topic (thermal technologies in food preservation), and the final sentence contrasts ohmic heating with conventional heating to show its benefit.
**Choice A is incorrect.** The passage does not suggest flaws in ohmic heating; it notes recent research and characterizes ohmic heating as an improvement, not as problematic or under-researched.
**Choice C is incorrect.** Although the passage mentions research in Brazil, it does not provide an overview of global research; that detail is brief and not the main purpose.
**Choice D is incorrect.** The passage does not explain why conventional methods are popular nor does it propose a policy or widespread shift away from them; it merely contrasts their mechanism with that of ohmic heating.
**Faster approach:** Find the sentence that names the topic and the sentence that states its significance or advantage; choose the answer that matches both the topic (ohmic heating) and its main point (benefit over conventional methods).'),
  ('889c2356-58c9-5f19-99aa-d8c2e699a24e', 2, null, '**Choice C is correct.** The kestrel image is used as a parallel to the speakers'' shared quiet: the bird "mutes his mating-note / To please the harmony of this sweet silence," which mirrors how the speaker and friend accept and contribute to the same calm atmosphere. The reference aligns the natural world with the pair’s experience, reinforcing the poem’s depiction of mutual, peaceful understanding.
**Choice A is incorrect.** The lines do not imply mystery; they give a clear, intentional action by the kestrel that parallels the speakers’ silence rather than suggesting nature’s inscrutability.
**Choice B is incorrect.** The speaker does not accuse the friend of withholding true feelings; instead, both "knew all the other said," and the kestrel’s muting suggests consonance, not concealment.
**Choice D is incorrect.** The poem does not discuss changing definitions of peace between people; instead it highlights a shared, mutual silence, so the kestrel image supports uniformity of experience rather than variability in the meaning of peace.
**Faster approach:** Identify whether the figurative image reinforces similarity or contrast with the speakers—if it parallels their state, choose the option about alignment; if it introduces tension, choose concealment or mystery.'),
  ('3829338d-187a-5b52-a282-638e232b41ef', 2, null, '**Choice C is correct.** The passage says the front parlor "had always been her special province, as she used it for her little school," and that after the salon it was "never in order for its transformation back to a classroom the following morning." Tia Ana "had already come into the room several times to see if these guests had departed yet," which directly indicates she wants the gathering to end so she can prepare the space for her school.
**Choice A is incorrect.** The text gives no evidence that she finds the guests dull or is trying to leave the salon herself; it emphasizes her concern about the room’s readiness, not boredom.
**Choice B is incorrect.** There is no mention of Tia Ana wanting to advertise a new school or seeking guests’ approval; the passage focuses on her use of the room for her existing little school.
**Choice D is incorrect.** The passage does not mention other household needs or that Salomé is unavailable; Tia Ana’s repeated visits are tied to preparing the room for school rather than seeking help elsewhere.
**Faster approach:** Look for explicit statements about characters’ routines and possessions ("special province," "little school") and connect them to actions (checking if guests left) to infer motivation quickly.'),
  ('14e975ef-c7be-5546-86cc-810c4aaf0f9c', 1, null, '**Choice B is correct.** The passage states that Villasana celebrates cultural icons (for example, Muhammad Ali) and also honors ordinary people (for example, a woman making tortillas), and it explicitly says she sees both approaches as ways of depicting the "power and interconnectedness of all people," which matches this choice.
**Choice A is incorrect.** The passage does not say she began with famous people and later switched to everyday people; it simply describes both approaches without implying a chronological sequence.
**Choice C is incorrect.** The passage does not claim that the tortilla portrait emphasizes connection more than resilience; it says Villasana uses both types of works to depict "power and interconnectedness," treating both aspects together.
**Choice D is incorrect.** The passage gives no information about scholarly attention or which depiction receives more attention; it only describes the subjects Villasana portrays.
**Faster approach:** Look for language that summarizes the artist’s purpose (here, "power and
interconnectedness of all people") and match that central idea to the choice that restates it directly.'),
  ('2126c2d2-b9bf-592c-aa81-677c9b810160', 1, null, '**Choice B is correct.** The table lists Nambe Pueblo (spelled “Nambe” in the table) with an area of $32.4$ square miles, so the student should fill the blank with "32.4 square miles." This directly uses the numeric entry in the table for Nambe Pueblo.
**Choice A is incorrect.** $47.3$ square miles is the area listed for Pueblo de San Ildefonso, not Nambe Pueblo.
**Choice C is incorrect.** $77.1$ square miles is the area given for Santa Clara Pueblo, not Nambe Pueblo.
**Choice D is incorrect.** $595.7$ square miles is the area of the Pueblo of Acoma, far larger than Nambe Pueblo’s area in the table.
**Faster approach:** Scan the table for the row labeled Nambe (or Nambé) Pueblo and read the adjacent area value; for any table question, locate the relevant row and use that number directly.'),
  ('4abb90cd-e25b-56b6-ace5-37c33c40efac', 1, null, '**Choice B is correct.** The plotted point for Lake Kallavesi in winter 1980–81 is near 175 days on the vertical axis, and the plotted point for 2005–06 is near 145 days, showing a decline of about 30 days and directly supporting the researcher’s claim.
**Choice A is incorrect.** The Spirit Lake points do not show values of approximately 100 and 125 days for 1980–81 and 2005–06; the graph places Spirit Lake at different values.
**Choice C is incorrect.** The highest number of days of ice for 2005–06 on the graph is about 145 (for Kallavesi), but the choice says "approximately 145" as the highest — while that matches numerically, the statement is presented as a general claim and choice B gives the specific data that supports the researcher’s claim more directly; moreover, the question asks which best describes data that support the claim, and B does so.
**Choice D is incorrect.** At least one lake (Kallavesi) had fewer days of ice in 2005–06 than in 1980–81, so it is not true that none had fewer days in 1980–81 than in 2005–06.
**Faster approach:** Read the two year labels on the x-axis, locate each lake’s two plotted points, and compare their y-values directly — the lake with a visibly lower 2005–06 point than 1980–81 point shows the decline described.'),
  ('b5c7c9fe-ca45-518d-833c-cc958a36a3dd', 1, null, '**Choice B is correct.** This option supports the journalist’s claim by highlighting that La Cage aux Folles, which received an Oscar nomination, had higher lifetime earnings than Padmaavat, which did not receive an Oscar nomination. Specifically, La Cage aux Folles earned \$20,424,259 in lifetime gross earnings, while Padmaavat earned \$11,846,060. This illustrates that films recognized by the Oscars can achieve greater long-term financial success than those that are not.
Now, let’s evaluate why the other choices are incorrect:
**Choice A** is incorrect because although it states that Cinema Paradiso had Oscar recognition and Instructions Not Included did not, it incorrectly concludes that the latter had higher lifetime earnings. In fact, Instructions Not Included earned \$44,467,206, which is higher than Cinema Paradiso’s \$11,990,401.
**Choice C** is incorrect because while both La Cage aux Folles and Cinema Paradiso were indeed recognized by the Oscars, it inaccurately claims that La Cage aux Folles had higher opening weekend earnings than Cinema Paradiso. La Cage aux Folles had an opening weekend gross of \$18,709, while Cinema Paradiso’s was \$16,552, which is correct, but C does not effectively support the journalist’s claim regarding correlation with lifetime earnings.
**Choice D** is incorrect because it focuses on Instructions Not Included and Padmaavat and mentions their opening weekend earnings; however, it does not provide any relevant information about how this relates to the journalist’s claim about Oscar nominations affecting lifetime earnings. Additionally, it fails to draw a comparison with successful Oscar-nominated films.'),
  ('5a737f5e-6aae-5030-b7f6-ee48390d25f7', 2, null, '**Choice C is correct.** The students claim that opposition is based on worries that increased car traffic would "diminish the distinctive character of the street." Choice C explicitly expresses that concern: the respondent calls Cuba Street "one of the most unusual streets" and says they would hate to see it become "just like any other street," directly linking more cars to loss of uniqueness.
**Choice A is incorrect.** That response complains about lack of consultation and representation, not about the street’s character being diminished by cars.
**Choice B is incorrect.** That comment focuses on economic effects—businesses losing foot traffic—not on the street losing its distinctive character.
**Choice D is incorrect.** That respondent objects to cars for environmental and proliferation reasons (noise and exhaust), which is different from the specific worry that cars would make the street lose its unique character.
**Faster approach:** Look for the choice that explicitly mentions loss of uniqueness or becoming "like any other street," since that wording directly matches "diminish the distinctive character."'),
  ('d52f645a-d287-5a93-ab47-31cb92b79bde', 2, null, '**Choice C is correct.** The passage states that nothing written before 1155 mentions the Round Table and that the Roman de Brut (1155) does include such references; therefore, it is most logical to infer that traditions mentioning the Round Table descend from or are connected to the Roman de Brut. This directly follows from the chronological claim about the earliest textual appearance of the Round Table.
**Choice A is incorrect.** The passage does not compare overall similarity of Geoffrey’s accounts with those in Tom a Lincoln or Roman de Brut; it only discusses the presence or absence of the Round Table before 1155.
**Choice B is incorrect.** The passage does not assert Geoffrey’s awareness or lack thereof of Round Table stories, only that nothing written before 1155 contains such references, so we cannot conclude what Geoffrey knew.
**Choice D is incorrect.** The passage gives no basis for judging historical accuracy of Roman de Brut versus History; it only notes dates and the appearance of the Round Table, not accuracy or influence of Tom a Lincoln.
**Faster approach:** Use the dates as anchors — identify the earliest text that contains the detail and conclude later texts with that detail likely derive from it.'),
  ('c3995be2-43ba-51c4-92d5-7fe14a79c5e2', 3, null, '**Choice D is correct.** The sentence lists examples of places, so it requires a simple comma-separated series: “libraries, train stations, and public squares.” Inserting “libraries, train” into the blank yields that correct series when read with the following word “stations.” The comma correctly separates list items and allows “train” to modify “stations.”
**Choice A is incorrect.** A colon (“libraries: train”) would introduce a list or explanation, which does not fit the simple series of examples and breaks the flow into an illogical fragment.
**Choice B is incorrect.** With no punctuation (“libraries train”) the phrase reads as a fused noun phrase “libraries train stations,” which is ungrammatical and confusing.
**Choice C is incorrect.** An em dash (“libraries—train”) creates a pause or break inappropriate for a straightforward list and makes the sentence awkward and nonparallel.
**Faster approach:** For items in a list, use commas to separate parallel nouns; insert a comma when you see three or more list elements.'),
  ('9d582a34-8434-5e85-a3c9-93aed1ee0cae', 3, null, '**Choice D is correct.** The novel title functions as a nonrestrictive appositive phrase set off from the rest of the sentence; punctuation after the title should be a comma to close that phrase: "...her 2020 novel Mexican Gothic, best known as a novelist." The comma correctly separates the noun phrase naming the novel from the clause describing the result.
**Choice A is incorrect.** An em dash is unnecessary and changes emphasis; it does not follow the standard convention for closing a nonrestrictive appositive within the flow of this sentence.
**Choice B is incorrect.** A semicolon cannot follow a noun phrase like a book title to connect to a dependent clause; semicolons join independent clauses, so it is grammatically wrong here.
**Choice C is incorrect.** Leaving no punctuation fails to set off the appositive and results in a run-on phrase that does not conform to Standard English punctuation for a nonrestrictive modifier.
**Faster approach:** Recognize the title as an appositive that needs to be set off from the rest of the sentence; always use a comma (not a semicolon or dash) to close a nonrestrictive appositive within a sentence.'),
  ('b3e1710d-126b-5c8c-997b-caff21f71e04', 1, null, '**Choice B is correct.** The sentence contains two independent ideas: (1) the exhibition "set out to provide a wide-ranging overview of photography by women in the 1920s through the 1950s" and (2) "given the collection’s breadth..., its efforts were largely successful." Joining these with ", and" correctly coordinates the two clauses while allowing the parenthetical introductory phrase "given the collection’s breadth of more than 120 photos" to modify the second clause.
**Choice A is incorrect.** A bare "1950s" followed by the comma already present after the blank creates a comma splice: two independent clauses improperly joined by a comma.
**Choice C is incorrect.** "1950s," still leaves a comma splice for the same reason as Choice A; it does not provide the coordinating conjunction needed to join the clauses correctly.
**Choice D is incorrect.** "1950s and" without the comma does not clearly separate the two independent clauses and makes the sentence clumsy and grammatically awkward; the safer, standard construction is ", and".
**Faster approach:** When two independent clauses appear, look for a coordinating conjunction (and, but, so, or, nor, for, yet) with a preceding comma. If a modifying introductory phrase follows, use ", and" to join the clauses cleanly.'),
  ('6f6ed300-4888-57ce-9878-888185785ed2', 1, null, '**Choice B is correct.** The subject of the clause is "many works," which is plural, so the verb must be a plural past passive form: "were considered." The parenthetical phrase "—particularly one abstract cubist painting by Marcel Duchamp—" does not change the main subject and should be ignored for subject-verb agreement, so "were considered" correctly matches "many works."
**Choice A is incorrect.** "Was" is singular and would incorrectly match the parenthetical noun phrase rather than the main plural subject "many works," producing a subject-verb disagreement.
**Choice C is incorrect.** "Has been" is singular (or plural with "have been") and present perfect, which mismatches the past timeframe indicated by "at the time" and does not agree with the plural subject without changing to "have been."
**Choice D is incorrect.** "Is" is present tense and singular, creating both a tense mismatch with "at the time" and a subject-verb disagreement with the plural subject "many works."
**Faster approach:** Identify the main subject outside any dashes or parentheses and make the verb agree in number and tense with that subject (ignore the parenthetical phrase when checking agreement).'),
  ('f02b456c-2c81-5fab-ac2c-ae3f72ddcab5', 0, null, '**Choice A is correct.** The clause beginning with "which" is nonrestrictive and therefore must be preceded by a comma; Choice A places a comma immediately after the artwork’s title, yielding "oil painting Uprising, which was created...," a grammatical and natural phrasing indicating that the painting named Uprising is the one created in 1910.
**Choice B is incorrect.** It omits the required comma before "which," producing a run-on where a nonrestrictive clause is not set off correctly.
**Choice C is incorrect.** It inserts a comma before the title but fails to include a comma after the title, leaving the nonrestrictive "which" clause unmarked.
**Choice D is incorrect.** It breaks the sentence into fragments with periods, disrupting the modifier "which was created in 1910" and producing ungrammatical sentence structure.
**Faster approach:** Whenever you see "which" introduce extra information, ensure there is a comma immediately before "which"; pick the option that supplies that comma.'),
  ('16399b4b-d34b-5171-83eb-0d7ba3260bd4', 0, null, '**Choice A is correct.** The sentence sets up a past narrative ("In 1987, chemist Ahmed Zewail devised...") and then refers to events that occurred later relative to that past moment. "Would be honored" is the correct future-in-the-past construction: from the 1987 standpoint, the honors happened years later, so "he would be honored" appropriately places those honors after the 1987 event while keeping the narrative in the past tense.
**Choice B is incorrect.** "Is honored" places the honors in the present, which conflicts with the past-time frame established by "devised."
**Choice C is incorrect.** "Will be honored" denotes a future relative to now, not the future-in-the-past needed here; it creates a tense mismatch with "devised."
**Choice D is incorrect.** "Had been honored" (past perfect) would place the honors before the 1987 event, which contradicts "Years later."
**Faster approach:** Identify the time frame set by the first verb ("devised" = past); then choose a tense that places the honors after that past time (use future-in-the-past: "would be honored").'),
  ('fa17a2a0-0a43-5157-9cc0-502451db46fe', 0, null, '**Choice A is correct.** The second sentence states a fact about dogs that parallels the first sentence’s fact about humans, so a transition signaling similarity is appropriate. "Similarly," directly links the two statements by showing that dogs, like humans, inherit specific physical traits from their parents.
**Choice B is incorrect.** "In other words," implies a restatement or clarification of the same idea rather than a comparison to a different subject, so it does not fit the shift from humans to dogs.
**Choice C is incorrect.** "As a result," indicates causation or consequence, which is not the relationship between the two sentences; the second sentence is not a consequence of the first.
**Choice D is incorrect.** "In conclusion," signals a final summary or wrap-up, which is inappropriate because the second sentence introduces a parallel example rather than concluding an argument.
**Faster approach:** Look for whether the second sentence gives a similar example, a restatement, a cause, or a conclusion; choose the transition that matches that relationship—here, a similarity, so pick "Similarly."'),
  ('9194a8aa-63cd-5d69-bad9-f2c11f2954f9', 1, null, '**Choice B is correct.** The two clauses set up a cause-and-effect relationship: because Le Guin wrote in two different genres, it follows that readers from both genres would be among her audience. "Accordingly" signals that what follows is a logical consequence of the previous statement, so "Accordingly, both fans of science fiction and fans of fantasy are among her many readers." is the best fit.
**Choice A is incorrect.** "Alternatively" suggests an either/or choice or substitution, which does not match the intended logical consequence connecting the two sentences.
**Choice C is incorrect.** "Nevertheless" signals contrast or surprise; the second sentence is not presenting a surprising exception to the first, so it is inappropriate.
**Choice D is incorrect.** "At that time," is a temporal marker; the sentence requires a logical connector rather than a time reference.
**Faster approach:** Identify the logical relationship (cause/effect, contrast, alternative, or time) and eliminate choices that signal different relationships; pick the transition that matches the identified logic.'),
  ('4ab30b05-3133-5dc4-9c52-072c2fa55f08', 2, null, '**Choice C is correct.** The notes state that both kale and carrots contain ascorbic acid, and that ascorbic acid is also known as vitamin C. Choice C directly names the shared attribute—both vegetables contain vitamin C —succinctly emphasizing the similarity between kale and carrots.
**Choice A is incorrect.** This sentence focuses only on carrots and the amount of ascorbic acid they contain; it does not emphasize a similarity between kale and carrots.
**Choice B is incorrect.** Although it mentions kale and the need for vitamin C, it emphasizes humans’ inability to make vitamin C and suggests vegetables in general rather than stating a similarity between kale and carrots.
**Choice D is incorrect.** This choice compares fruits and vegetables and notes that vegetables provide vitamin C, but it does not explicitly state that kale and carrots share that specific trait.
**Faster approach:** Look for the answer that names the same specific attribute for both items (here, "contain vitamin C").'),
  ('4c9a02a1-fb41-5a38-a2fb-c9a1a5e84318', 0, null, '**Choice A is correct.** It directly links the relevant factual information from the notes — that the water in brine pools is "three to eight times saltier than the surrounding ocean" — to the stated consequence that this extreme saltiness "makes it toxic to most sea life," providing the clear explanation the student wants.
**Choice B is incorrect.** It combines the toxicity claim with the discovery detail (2022) but does not explain why the pools are toxic; the discovery date is irrelevant to the cause.
**Choice C is incorrect.** It notes that some bacteria survive, which is relevant background, but it fails to explain why most sea life cannot survive there.
**Choice D is incorrect.** It defines brine pools and location but does not explain the reason for their toxicity.
**Faster approach:** Choose the option that states the cause-and-effect relationship from the notes (salinity causes toxicity).'),
  ('fd178eff-cb94-5a72-80b4-0332f7ed39e6', 1, null, '**Choice B is correct.** It directly specifies the location where Discoglossus nigriventer was identified: Israel. It also concisely includes the relevant background (previously believed extinct) without adding unrelated details, matching the student’s goal of specifying where the species was identified.
**Choice A is incorrect.** It names the location (New Zealand) and date for Dysphania pusilla, not Discoglossus nigriventer, so it does not answer the question about where Discoglossus nigriventer was identified.
**Choice C is incorrect.** It generalizes that both are examples of Lazarus species but does not state the location where Discoglossus nigriventer was found, so it fails to specify the required place.
**Choice D is incorrect.** It gives the correct year (2011) and extinction status for Discoglossus nigriventer but omits the location (Israel), so it does not fully accomplish the student’s goal.
**Faster approach:** Look for the question word (here, “where”) and choose the answer that explicitly names a place; eliminate choices that give dates or examples without a location.'),
  ('2e9f8ac8-e0d6-585f-9f7e-d392e87cc586', 1, null, '**Choice B is correct.** It directly emphasizes a similarity by stating that both Margaretta Morris and Emilie Snethlage dedicated their scientific careers to studying living organisms (Morris studied insects and Snethlage studied birds), which correctly synthesizes the notes about their professional focus.
**Choice A is incorrect.** It highlights a difference in birth years rather than emphasizing any similarity between the two scientists.
**Choice C is incorrect.** It makes a general statement about scientific fields rather than drawing a specific similarity between Morris and Snethlage.
**Choice D is incorrect.** It explicitly contrasts their research areas ("by contrast"), which emphasizes differences rather than a shared similarity.
**Faster approach:** Look for wording that explicitly compares the two people (words like "like," "both," or "shared") and refers to their similar roles or activities; eliminate choices that focus on differences or make only general statements.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

-- PeaklyTest Mar 2024 · Reading & Writing · Module 2
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('8fa94518-02d2-5455-b637-c7942c479826', 'PeaklyTest Mar 2024 · Reading & Writing · Module 2', 'Reading & Writing', 'Reading & Writing, Module 2 of the Mar 2024 PeaklyTest · 27 questions · 32 minutes', 32, 301, true, 'PeaklyTest Mar 2024 · Reading & Writing', 2)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('5bf4cbb0-5942-5287-9f38-232f7b1014f4', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice completes the text with the most logical and precise word or phrase?', '["blamed", "applauded", "misunderstood", "overlooked"]'::jsonb, 1, 'The reception of Ji-li Jiang’s book Red Kite, Blue Kite has been very good. Many reviewers have _____ the book, and it won the Asian/Pacific American Award for Literature.'),
  ('73500693-2da3-55c5-8737-93cc07cfc24c', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice completes the text with the most logical and precise word or phrase?', '["insight into", "obliviousness about", "exceptions to", "hesitancy about"]'::jsonb, 2, 'At a conference for aspiring children’s book authors, Candy Dawson Boyd, author of such lauded works as Circle of Gold, was the subject of a presentation that was intended specifically to foster ______ the techniques of successful authors so that attendees could use that understanding to improve their own work.'),
  ('626b3f79-0ddb-5ee4-8e98-7f1164ffac6f', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice completes the text with the most logical and precise word or phrase?', '["uncontroversial", "unknown", "unalterable", "unsurprising"]'::jsonb, 3, 'The Sydney rock engravings—stone carvings of human and animal figures found in what is now Australia and dating from 5,000–7,000 years ago—are thought of as art today, but how the people of the time understood the engravings is _____. They may have thought of the engravings as something akin to art in our modern sense, but it is entirely possible that they did not—we simply cannot say for certain.'),
  ('88e6d208-3ba3-5f4f-88dc-43777564e4e4', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice completes the text with the most logical and precise word or phrase?', '["utilize", "influence", "undermine", "assess"]'::jsonb, 4, 'One way to _____ the importance of a scholar’s research is to track how often other scholars refer to that research. For example, Harvard University economist Claudia Goldin, who studies gender and economics, is among the world’s most frequently cited researchers in her field, indicating that her work has been quite significant.'),
  ('e972e040-f6c7-5d5e-8bcf-d4e244d394ce', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice best describes the function of the underlined portion in the text as a whole?', '["It describes the imprecise and subjective nature of neighborhood boundaries.", "It emphasizes the potential utility of the team’s model.", "It introduces a model that a research team built to evaluate the mix of amenities in urban neighborhoods.", "It identifies a specific flaw in using a data set about amenities in cities."]'::jsonb, 5, 'Researchers César A. Hidalgo, Elisa Castañer, and Andres Sevtsuk created a computer model to predict the mix of businesses and places of interest found in a given neighborhood. The team used data from the Google Places API service to help identify electronics stores, bakeries, and other businesses and map their locations. This approach has some limits—<u>data from Places API tend to be restricted to places</u> <u>that are customer facing</u>—but the data set nonetheless provides an extremely reliable source to study colocation patterns of neighborhood amenities.'),
  ('b43afdef-04ea-575e-adca-74f64a29fa6d', '8fa94518-02d2-5455-b637-c7942c479826', 'Based on the texts, how would the author of Text 2 most likely respond to the claim in the underlined sentence in Text 1?', '["By suggesting that whatever infractions Luttrell might have committed are outweighed by the cultural value of the Luttrell Psalter.", "By agreeing that though the law might have permitted Luttrell to do so, Luttrell was wrong to have raided Sempringham Priory.", "By pointing out that if Luttrell had taken the actions of which he is accused, then there would be documentation of those actions in the Luttrell Psalter.", "By asserting that a consideration of Luttrell’s behavior should take into account that he believed his actions were justified."]'::jsonb, 6, '**Text 1**

Sir Geoffrey Luttrell funded the creation of the Luttrell Psalter, notable for its portrayal of life on a 14th-century English estate. Not all of Luttrell’s actions were admirable, however. Most infamously, he participated in what was essentially a private war against Sempringham Priory, a monastery near his manor, even making off with 500 pounds'' worth of monastery property during a raid. <u>So Luttrell''s</u> <u>reputation should be regarded as questionable at best.</u>

**Text 2**

Some historians claim that Luttrell’s poor treatment of his neighbors is as crucial to his biography as his funding of the Luttrell Psalter. But his conflict with Sempringham Priory must be seen as an indirect result of a property dispute involving land on which his manor sat: he was taking property to which he thought he had a right.'),
  ('e72a9544-03c1-51ae-af40-625eede30c6f', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice best states the main idea of the text?', '["Historians are more interested in the lives of famous people than in those of the less famous.", "The creativity of historians is restricted by the need to write strictly truthful works.", "The lives of historical figures are usually documented as a collection of facts, rather than as a representation of their personalities.", "Paintings may be more beautiful than maps, but maps are more useful than paintings."]'::jsonb, 7, 'The following text is from Nathaniel Hawthorne’s 1830 short story “Sir William Phips.”
Few of the personages of past times (except such as have gained renown in fireside legends as well as in written history) are anything but mere names to their successors. They seldom stand up in our imaginations like men. The knowledge, communicated by the historian and biographer, is analogous to that which we acquire of a country by the map—minute, perhaps, and accurate, and available for all necessary purposes, but cold and naked, and wholly destitute of the mimic charm produced by landscape painting.'),
  ('cdb96b97-e939-58cd-9de1-dfeaae0e4325', '8fa94518-02d2-5455-b637-c7942c479826', 'According to the text, which trait do researchers think may contribute to a rusty-spotted cat’s ability to purr?', '["The ligament attaching the hyoid bone to the rusty-spotted cat’s skull.", "The relative size of the rusty-spotted cat’s body and throat.", "The rusty-spotted cat’s rigid hyoid bone.", "The shape of the rusty-spotted cat’s larynx."]'::jsonb, 8, 'Why do rusty-spotted cats purr but lions roar? Researchers hypothesize that this difference between the two feline species may be partly due to a U-shaped bone in their throats called the hyoid. Rusty-spotted cats, which are much smaller than lions, have a rigid hyoid that rumbles when the cat’s larynx vibrates, resulting in a purr. By contrast, lions have a somewhat flexible hyoid, and the bone is attached to the skull with a stretchy ligament that rusty-spotted cats lack. These traits allow lions and most other species of big cats to produce powerful roars. The same traits may also prevent most big cats from purring.'),
  ('aa0b1f9c-8e7b-5a7e-81bd-d3551e892f0c', '8fa94518-02d2-5455-b637-c7942c479826', 'What does the text suggest about the Turkins?', '["They are relative newcomers to the city of S.", "They have a unique status in the city of S.", "They are amused by the other residents of the city of S.", "They have long disliked living in the city of S."]'::jsonb, 9, 'The following text is from Anton Chekhov’s 1898 short story “Ionitch” (translated by Marian Fell in 1915). The text is set in a Russian city referred to as the city of S.

If newcomers to the little provincial city of S. complained that life there was monotonous and dull, its inhabitants would answer that, on the contrary, S. was a very amusing place, indeed, that it had a library and a club, that balls were given there, and finally, that very pleasant families lived there with whom one might become acquainted. And they always pointed to the Turkins as the most accomplished and most enlightened family of all.'),
  ('8f519886-5951-5072-b4b0-e59ef1ed2015', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice most effectively uses data from the table to complete the statement?', '["Ambassadors.", "Brownies.", "Daisies.", "Cadettes."]'::jsonb, 10, '**Members of the Girl Scouts of America, by Age Category. 1992–1995 (in thousands)**

| Category | 1992 | 1993 | 1994 | 1995 |
| Brownies (6-8 years) | 1,319 | 1,225 | 1,181 | 1,142 |
| Ambassadors (older than 17) | 863 | 826 | 802 | 784 |
| Daisies (5-6 years) | 207 | 191 | 190 | 195 |
| Cadettes (11-14 years) | 188 | 168 | 174 | 172 |

The Girl Scouts of America is a youth organization that had just over 1 million members in 2021. A student is writing an essay on the history of the organization and wishes to determine which of four categories of Girl Scouts had the most members in 1993. (Girl Scout categories correspond roughly with ages.) According to the table, the category with the most members in 1993 was the _____'),
  ('6ed4f959-3724-5b67-a03d-60b6a1a73e8d', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice best states the main purpose of the text?', '["It contrasts the tranquility of the waters near Puerto Cabello with the roughness of waters elsewhere.", "It emphasizes the severity of a storm that is expected to arrive soon in Puerto Cabello.", "It compares the sturdiness of two types of boats.", "It describes the speaker’s appreciation for the people of Puerto Cabello."]'::jsonb, 11, 'The following text is adapted from D.A. Lozano’s 1844 poem “A Remembrance of Puerto Cabello— The Mangle” (translated by Agnes Blake Poor in 1918). The poem is a dedication to Puerto Cabello, a town on the northern coast of Venezuela.
And while outside the tempest is raving o’er the ocean,
And the ship is madly driving on some lone and desert shore;
Thy warm and land-locked waters swell with an easy motion,
And gently glides the light pirogue [canoe] at dipping of the oar.'),
  ('53b5175d-8e32-55ca-84a6-48c29cced1de', '8fa94518-02d2-5455-b637-c7942c479826', 'Which finding, if true, would most directly support the team’s claim?', '["The genetic mutation exists in an ancestor of domestic dogs dating to 53,000 years ago.", "Wolves are related to domestic dogs but are much bigger than Pomeranians.", "Some domestic dog breeds that do not have the genetic mutation are very large.", "Dogs vary in size more than any other type of land mammal does."]'::jsonb, 12, 'Elaine Ostrander led an international study of domestic dogs with Kevin Bevant and other researchers to explore what causes very small breeds, such as Pomeranians, to be so small. Scientists once thought that smaller dogs came about only after humans started deliberately breeding dogs within the last 12,000 years. But Ostrander’s team claims that a certain genetic mutation strongly affects dog size and that the mutation existed long before humans started breeding dogs.'),
  ('e58cb218-bb4e-534d-a3fd-2c1ffa102547', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice most logically completes the text?', '["a confirmation of previous theories about the type of wood that was used in sixteenth-century ships.", "first constructed much earlier than previously thought.", "one of several other ships buried in the same quarry.", "covered by a protective sediment layer in the quarry."]'::jsonb, 13, 'Marine archaeologists have found much of the wooden hull of a sixteenth-century ship in a flooded quarry in southeast England. When it is exposed to air and water, wood rots quickly unless it is protected by sediment that shields it from oxygen. Therefore, the discovered ship was likely ______'),
  ('42507f15-1bc4-543c-8469-dcd8823f7553', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice most logically completes the text?', '["long-term trends in economic well-being are hard to find without collecting data over many years.", "fitness studies are not likely to require data from very many individuals.", "long-term trends in fitness can be found without examining many years of data.", "data from 25,000 people may not be enough to reveal significant trends in economic well-being."]'::jsonb, 14, 'Some studies can be done well with relatively little money. For example, a fitness study simply trying to identify the percentage of regular exercisers in a city who do weight training has a straightforward central question that doesn’t require many years of data collection. But it is much more expensive to conduct a longitudinal study like the Household, Income and Labour Dynamics in Australia Survey (HILDA), which looks at data for 25,000 people in Australia to find trends in economic well-being that can take a long time to develop. This requires lots of funding because _____'),
  ('9006e819-c90d-5303-b04f-13db4ac9c0c9', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice most logically completes the text?', '["the studies of the birds likely found significantly larger effects of exposure to anthropogenic noise than most studies of mammals except the study of brown rats by Soledad Lucia Uran and colleagues.", "the study conducted by Soledad Lucia Uran and colleagues found substantial differences, but studies included in the meta-analysis of mammals other than brown rats likely did not.", "exposure to anthropogenic noise will likely have noticeable effects both on mammals such as brown rats and on birds such as European robins, but the nature of that effect could be very different for the two species.", "the studies in the meta-analysis that examined mammals were more likely than those about birds to specify whether the observed effects were detrimental."]'::jsonb, 15, 'Anthropogenic noise (sounds from human sources like traffic or mining) can affect animals, as Soledad Lucía Uran and colleagues found in a 2012 study of brown rats. A meta-analysis of more than 100 such studies examining various species found that, for every study, relevant traits or behaviors of the animals were observably different between the exposed group and the otherwise similar but unexposed group, regardless of whether that difference was beneficial or detrimental for the exposed group. So while a study of birds might show a difference that benefits the exposed group, and a study of mammals might show a difference that’s harmful to the exposed group, both differences are substantial. Therefore, the results of the meta-analysis suggest that _____'),
  ('35012233-ddbf-5940-b0d2-d0afd06701b5', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["is collecting", "will collect", "has collected", "collects"]'::jsonb, 16, 'In 2019, the Russian Federation produced 27,016 hectograms per hectare (hg/ha) of wheat, and Serbia produced 43,890 hg/ha. This is the type of information on global food production that the United Nations'' Food and Agriculture Organization _____ since 1945.'),
  ('dbae7035-005a-58d5-b735-f1cbc5d686d2', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["on;", "on,", "on:", "on"]'::jsonb, 17, 'Today’s US currency features mainly former presidents. However, it was once common for images of nonpresidents such as Robert Fulton, the inventor of the steamboat, to appear _____ US currency.'),
  ('d8c69d7a-ac78-5a67-93c1-6e3a9718c9a7', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["these", "that", "this", "each"]'::jsonb, 18, 'Both Nakuru, Kenya, and Ibarra, Ecuador, are located at less than one degree latitude. In other words, _____ cities basically sit right on the equator!'),
  ('34170998-6ba9-5e13-8e97-0e26d0ab26b8', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["to translate", "translating", "having translated", "translates"]'::jsonb, 19, 'Many folktales that originate in the Hindi language begin with the same phrase. In English, this phrase _____ roughly to “it’s an old story.”'),
  ('9396a0d5-64fe-5680-bcff-bbae2ebc7e74', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["is being", "was", "will be", "is"]'::jsonb, 20, 'With residents from Mexico, China, El Salvador, and many other countries, Los Angeles has long been a city of cultural diversity. Even back in the 1860s, nearly 30% of the city’s population _____ from outside the United States.'),
  ('510babff-4ac9-5cbe-9346-1fbd845e1696', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["STS-96, and the", "STS-96. The", "STS-96 the", "STS-96, the"]'::jsonb, 21, 'Though it was designated as mission _____ mission was actually the ninety-fourth flight under NASA’s Space Shuttle Program.'),
  ('910368a4-33e9-5e18-819c-0d1de89abe4a', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice completes the text with the most logical transition?', '["In fact,", "Earlier,", "In any case,", "Instead,"]'::jsonb, 22, 'In eastern Mexico, Monument 5 and Monument 2 are the names given to two massive human head statues that were left behind by the ancient Olmec civilization. Both statues are made of stone and are extremely heavy. _____ they each weigh more than 5 tons!'),
  ('5e4c9413-d3fd-5213-8eab-28d9d41224c6', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice completes the text with the most logical transition?', '["In fact,", "Besides,", "For example,", "Finally,"]'::jsonb, 23, 'Ecologists, such as Gerardo R. Camilo, use trophic pyramids to illustrate the food chain within a given ecosystem. At a typical pyramid’s base are primary producers, like phytoplankton, followed by herbivores at the second trophic level, then omnivores and carnivores at the third. ___ at the fourth, highest trophic level are apex predators, like sharks, that feed on the animals below.'),
  ('6f04ef97-029c-5fa1-9b69-1809d483645c', '8fa94518-02d2-5455-b637-c7942c479826', 'Which choice completes the text with the most logical transition?', '["Conversely,", "Finally,", "Nevertheless,", "Specifically,"]'::jsonb, 24, 'Stephaney Smith has worked at NASA’s famed Jet Propulsion Laboratory (JPL), one of the world’s leading facilities for robotic space exploration. _____ Smith worked as a hardware quality assurance engineer on JPL’s Mars 2020 Perseverance rover team, which improved upon the 2011 Curiosity rover design by adding a coring drill to the robot that could collect rock samples for later analysis.'),
  ('07b3977e-fbb6-558e-ba2b-6206f58cc91c', '8fa94518-02d2-5455-b637-c7942c479826', 'The student wants to introduce Elizabeth Catlett to an audience unfamiliar with the artist. Which choice most effectively uses relevant information from the notes to accomplish this goal? Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["In contrast to the 1971 sculpture Political Prisoner, which is made of cedar, the 1980 sculpture Singing Head is made of marble.", "Political Prisoner is a cedar sculpture that was created in 1971.", "The sculpture Political Prisoner was made in 1971, and the sculpture Singing Head was made in 1980.", "Elizabeth Catlett, a celebrated African American artist, is best known for creating sculptures and prints that explore the Black experience."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

Elizabeth Catlett (1915–2012) was a celebrated African American artist.
She is best known for creating sculptures and prints that explore the Black experience. Political Prisoner is a 1971 cedar sculpture by Catlett.
Singing Head is a 1980 marble sculpture by Catlett.'),
  ('41cf2a1c-ec50-50f1-9422-d35e5e1e183c', '8fa94518-02d2-5455-b637-c7942c479826', 'The student wants to emphasize whose point of view the novel is told from. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["<u>Kaikeyi</u> is a retelling of <u>The Ramayana</u> from the character Kaikeyi’s point of view.", "From the point of view of <u>The Ramayana</u>, the character Kaikeyi is often a villain.", "Vaishnavi Patel often portrays the character as heroic.", "<u>The Ramayana</u> is an epic poem that features the character Kaikeyi."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

The Ramayana is a Sanskrit epic poem from ancient India.
In The Ramayana, the character Kaikeyi is often portrayed as a villain.
Kaikeyi is a 2022 novel by Vaishnavi Patel.
The novel is a retelling of the epic poem from Kaikeyi’s point of view.
It often portrays Kaikeyi as heroic.'),
  ('0aa00268-e11e-5556-9640-d009ea1cf18f', '8fa94518-02d2-5455-b637-c7942c479826', 'The student wants to emphasize a difference between the two compositions. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Live On, Heart of My Nation and Fantasy Aborigine No.3 are two compositions written by Ballard, a classical music composer.", "In his two compositions Live On, Heart of My Nation and Fantasy Aborigine No.3, Ballard blends elements of various Native musical traditions, such as Indigenous hymns or instruments, with Western classical music.", "While both compositions integrate various Native musical traditions, Live On, Heart of My Nation does so by featuring a Choctaw hymn and Fantasy Aborigine No.3 does so by incorporating a Tewa seashell rattle.", "Ballard has different approaches to blending Western classical music with elements of various Native musical traditions, such as using Indigenous hymns and instruments in his compositions."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Louis Ballard was a classical composer and citizen of the Quapaw Tribe.
His compositions synthesize Western classical music with elements of various Native musical traditions.
Ballard’s classical piece Live On, Heart of My Nation features a Choctaw hymn.
Ballard’s classical piece Fantasy Aborigine No.3 incorporates a Tewa seashell rattle, a traditional Native instrument.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('5bf4cbb0-5942-5287-9f38-232f7b1014f4', 1, null, '**Choice B is correct.** The sentence says the reception "has been very good," so the missing word must have a positive meaning. "Applauded" means praised or warmly received, which fits perfectly with a positive reception and the follow-up that the book won an award.
**Choice A is incorrect.** "Blamed" has a negative connotation and would contradict the statement that the reception was very good.
**Choice C is incorrect.** "Misunderstood" implies critics failed to grasp the book, which doesn’t match a description of a very good reception and an award.
**Choice D is incorrect.** "Overlooked" means ignored or not noticed; that conflicts with the claim that many reviewers engaged positively and that the book won an award.
**Faster approach:** Note the positive context word "very good," then eliminate choices with negative meanings (blamed, misunderstood, overlooked) to select the positive synonym "applauded."'),
  ('73500693-2da3-55c5-8737-93cc07cfc24c', 0, null, '**Choice A is correct.** The sentence describes a presentation intended to help aspiring authors learn from Candy Dawson Boyd so they could improve their own work; "insight into the techniques of successful authors" precisely matches that purpose. "Insight into" means gaining understanding or awareness, which fits the context of a teaching presentation.
**Choice B is incorrect.** "Obliviousness about" means a lack of awareness, which conflicts with the presentation’s goal of fostering useful understanding.
**Choice C is incorrect.** "Exceptions to" would suggest focusing on cases that do not follow the techniques, which does not align with teaching attendees how to use successful techniques.
**Choice D is incorrect.** "Hesitancy about" implies reluctance or doubt, not the acquisition of knowledge; it therefore does not suit the intended purpose of the presentation.
**Faster approach:** Look for the option that denotes gaining understanding or knowledge ("insight into") whenever the context involves learning or instruction.'),
  ('626b3f79-0ddb-5ee4-8e98-7f1164ffac6f', 1, null, '**Choice B is correct.** The sentence contrasts modern interpretation with the uncertainty about past interpretation: "They may have thought... but it is entirely possible that they did not—we simply cannot say for certain." The word "unknown" precisely expresses that the way people at the time understood the engravings is not known.
**Choice A is incorrect.** "Uncontroversial" means not disputed or causing disagreement, which conflicts with the following clause that states we cannot say for certain.
**Choice C is incorrect.** "Unalterable" refers to something that cannot be changed; the passage is about knowledge or certainty, not changability.
**Choice D is incorrect.** "Unsurprising" means expected or not surprising, which is unrelated to the passage’s point about lack of knowledge.
**Faster approach:** Look for a word meaning "not known/uncertain" by matching the sentence’s contrast and the explicit phrase "we simply cannot say for certain." This immediately narrows choices to the synonym "unknown."'),
  ('88e6d208-3ba3-5f4f-88dc-43777564e4e4', 3, null, '**Choice D is correct.** The sentence describes a method for determining a scholar’s standing by tracking how often others cite their work; to "assess the importance" fits precisely because tracking citations is a way of evaluating significance.
**Choice A is incorrect.** "Utilize the importance" is ungrammatical and illogical: one does not "utilize" an abstract quality like importance in the way the sentence requires.
**Choice B is incorrect.** "Influence the importance" changes the meaning to imply changing or affecting importance rather than measuring it, which contradicts the intended idea of tracking citations as an evaluative method.
**Choice C is incorrect.** "Undermine the importance" implies decreasing or weakening importance, which is not conveyed by counting citations; the sentence intends measurement, not reduction.
**Faster approach:** Use elimination—replace the blank with each option and discard choices that produce illogical or ungrammatical phrases; the one that yields a coherent evaluative meaning ("assess") is correct.'),
  ('e972e040-f6c7-5d5e-8bcf-d4e244d394ce', 3, null, '**Choice D is correct.** The underlined phrase calls out a limitation of the data source—that the Places API is limited to customer-facing locations—so it functions to identify a specific flaw in using that data set to study neighborhood amenities.
**Choice A is incorrect.** The phrase says nothing about how neighborhood boundaries are defined; it addresses the scope of the data, not the location or ambiguity of neighborhood borders.
**Choice B is incorrect.** The clause highlights a restriction (a drawback) of the data, rather than emphasizing the utility or benefits of the model.
**Choice C is incorrect.** The model and its purpose are introduced earlier; the underlined clause does not introduce the model but points out a limitation of the data used.
**Faster approach:** Look for language that signals limitation words ("restricted," "limited," "tend to") to spot answer choices about flaws or caveats quickly.'),
  ('b43afdef-04ea-575e-adca-74f64a29fa6d', 3, null, '**Choice D is correct.** Text 2 explains that Luttrell’s conflict with the priory "must be seen as an indirect result of a property dispute" and that "he was taking property to which he thought he had a right." That language shows the Text 2 author wants judgments of Luttrell to account for his belief that his actions were justified, which directly counters Text 1’s unilateral claim that his reputation "should be regarded as questionable at best."
**Choice A is incorrect.** Text 2 does not argue that the Psalter’s cultural value outweighs Luttrell’s infractions; it offers a causal explanation for his behavior, not a value judgment balancing art against wrongdoing.
**Choice B is incorrect.** Text 2 does not state that Luttrell was legally permitted yet morally wrong; it emphasizes his perceived right to the property rather than condemning his moral culpability.
**Choice C is incorrect.** There is no claim in Text 2 that accusations would appear in the Psalter; the passage treats the Psalter and the property dispute separately.
**Faster approach:** Look for words indicating motive or justification (e.g., "thought he had a right," "result of"), and pick the answer that reflects that the author would emphasize Luttrell’s justification rather than simply condemning him.'),
  ('e72a9544-03c1-51ae-af40-625eede30c6f', 2, null, '**Choice C is correct.** The passage argues that historical knowledge provided by historians and biographers is like a map: "minute, perhaps, and accurate, and available for all necessary purposes, but cold and naked," lacking the "mimic charm produced by landscape painting." This comparison supports the main idea that historical figures are often recorded as factual information rather than portrayed with vivid personality.
**Choice A is incorrect.** The passage does not claim historians prefer famous lives; it discusses how historical accounts present people rather than historians'' interests.
**Choice B is incorrect.** The passage does not say historians are creative but constrained by truthfulness; it focuses on the tone and completeness of historical representation.
**Choice D is incorrect.** Although the passage uses the map/painting analogy, its point is about how people are represented (cold facts vs. vivid portrayal), not a value judgment that maps are more useful than paintings.
**Faster approach:** Spot the central analogy (map vs. painting) and choose the answer that describes the broader claim it supports—here, facts over vivid characterization.'),
  ('cdb96b97-e939-58cd-9de1-dfeaae0e4325', 2, null, '**Choice C is correct.** The passage states that rusty-spotted cats “have a rigid hyoid that rumbles when the cat’s larynx vibrates, resulting in a purr,” directly linking a rigid hyoid to the ability to purr.
**Choice A is incorrect.** The passage says lions have a ligament attaching the hyoid to the skull, not rusty-spotted cats; that ligament is associated with roaring, not purring.
**Choice B is incorrect.** Although the passage mentions that rusty-spotted cats are much smaller than lions, it does not say that relative body or throat size itself causes purring; the text emphasizes the hyoid’s rigidity.
**Choice D is incorrect.** The larynx vibrates to produce sound, but the passage identifies the rigid hyoid—not the shape of the larynx—as the trait researchers link to purring.
**Faster approach:** Scan the sentence that contrasts rusty-spotted cats and lions for the specific anatomical difference; the noun directly tied to purring is the correct answer.'),
  ('aa0b1f9c-8e7b-5a7e-81bd-d3551e892f0c', 1, null, '**Choice B is correct.** The passage says residents "always pointed to the Turkins as the most accomplished and most enlightened family of all," which indicates the Turkins occupy a special, high-status position in the city relative to other families.
**Choice A is incorrect.** Nothing in the passage says the Turkins are newcomers; the text describes them as an established example residents point to.
**Choice C is incorrect.** The passage calls the city "amusing" and lists attractions, but it does not say the Turkins themselves are amused by other residents.
**Choice D is incorrect.** The passage gives no evidence that the Turkins dislike living in S.; instead they are presented positively as accomplished and enlightened.
**Faster approach:** Look for direct descriptive phrases about the named subject—here "most accomplished and most enlightened"—to identify which answer reflects the stated status.'),
  ('8f519886-5951-5072-b4b0-e59ef1ed2015', 1, null, '**Choice B is correct.** The table shows the number of members (in thousands) for each category in 1993: Brownies — 1,225; Ambassadors — 826; Daisies — 191; Cadettes — 168. Because 1,225 is the largest value, Brownies had the most members in 1993.
**Choice A is incorrect.** Ambassadors had 826 members in 1993, which is less than Brownies’ 1,225, so Ambassadors were not the largest category.
**Choice C is incorrect.** Daisies had only 191 members in 1993, far fewer than Brownies’ 1,225.
**Choice D is incorrect.** Cadettes had 168 members in 1993, the smallest of the four listed figures and much less than Brownies’ total.
**Faster approach:** Scan the 1993 column and pick the largest number — here 1,225 for Brownies.'),
  ('6ed4f959-3724-5b67-a03d-60b6a1a73e8d', 0, null, '**Choice A is correct.** The passage sets up a direct contrast between two settings: a tempest raging “o’er the ocean” where “the ship is madly driving,” and the “warm and land-locked waters” of Puerto Cabello that “swell with an easy motion” while the “light pirogue” glides gently. The speaker’s main purpose is to show the calm, sheltered nature of the local waters in contrast with the rough seas elsewhere.
**Choice B is incorrect.** The passage does mention a storm, but the focus is not on emphasizing its severity in Puerto Cabello; rather, the storm is presented as occurring elsewhere while Puerto Cabello remains calm.
**Choice C is incorrect.** Although two boats are mentioned (a ship and a pirogue), the passage does not compare their sturdiness; it contrasts the different sea conditions and the resulting motion of the boats.
**Choice D is incorrect.** The speaker’s appreciation is directed to the waters and setting of Puerto Cabello, not to its people; no people are described or praised.
**Faster approach:** Look for contrast words or phrases (e.g., "and while," "but," or paired descriptions) to identify whether the passage is comparing two situations—this reveals the main purpose quickly.'),
  ('53b5175d-8e32-55ca-84a6-48c29cced1de', 0, null, '**Choice A is correct.** The team’s claim is twofold: a specific genetic mutation strongly affects size and that the mutation existed long before humans began deliberate breeding. Finding the mutation in an ancestor of domestic dogs dated to 53,000 years ago directly shows the mutation predates the 12,000-year timeframe for human-directed breeding, which most directly supports the claim.
**Choice B is incorrect.** That wolves are related but larger than Pomeranians is true but doesn’t address when the mutation arose or whether it existed before human breeding.
**Choice C is incorrect.** The existence of large breeds without the mutation says nothing about when the mutation first appeared; it only speaks to variability in size.
**Choice D is incorrect.** Greater overall size variation among dogs is irrelevant to the timing or existence of the specific mutation before human breeding.
**Faster approach:** Focus on the claim’s time component—pick the choice that places the mutation earlier than human breeding (evidence of ancient presence).'),
  ('e58cb218-bb4e-534d-a3fd-2c1ffa102547', 3, null, '**Choice D is correct.** The passage states that wood rots quickly when exposed to air and water unless it is protected by sediment that shields it from oxygen. Given that much of the wooden hull was found preserved, the most logical inference is that the ship was covered by a protective sediment layer in the quarry, which prevented decay.
**Choice A is incorrect.** The passage gives no information about types of wood used in sixteenth-century ships or how this find would confirm theories about wood species.
**Choice B is incorrect.** Nothing in the passage indicates the ship’s construction date relative to previous estimates; the preservation explanation relates to environment, not dating.
**Choice C is incorrect.** The passage mentions a single ship’s hull and provides no evidence that multiple ships were buried there.
**Faster approach:** Identify the causal statement (sediment prevents rot) and choose the option that directly follows from that cause (the ship must have been protected by sediment).'),
  ('42507f15-1bc4-543c-8469-dcd8823f7553', 0, null, '**Choice A is correct.** The passage contrasts a simple fitness study with a longitudinal study (HILDA) that tracks 25,000 people to find trends "that can take a long time to develop," and explicitly links that feature to higher cost; therefore it makes sense to complete the sentence by saying long-term trends are hard to find without many years of data.
**Choice B is incorrect.** The passage does say a fitness study may be simpler, but the expense of HILDA is tied to time and scope, not to the number of individuals required for fitness studies.
**Choice C is incorrect.** This contradicts the passage: it states long-term trends (in economic well-being) can take many years to develop, so they cannot be found without long-term data.
**Choice D is incorrect.** The passage presents 25,000 as the study sample size used to detect trends, not as evidence that the sample is insufficient; the main point is the need for long-term data, not sample size concerns.
**Faster approach:** Identify the cause-effect link in the sentence (what makes HILDA expensive) and choose the option that restates that cause concisely; here the passage already names the cause—long time—so pick the choice about needing many years of data.'),
  ('9006e819-c90d-5303-b04f-13db4ac9c0c9', 2, null, '**Choice C is correct.** The passage emphasizes that every study in the meta-analysis showed observable differences between exposed and unexposed groups, and that those differences can be beneficial for some species (birds) and detrimental for others (mammals). Choice C restates that exposure will likely produce noticeable effects across taxa (mammals and birds) while allowing that the direction of the effect can differ, matching the passage’s claim.
**Choice A is incorrect.** The passage does not compare effect sizes across taxa or claim that bird studies showed larger effects than mammal studies; it only says differences were observed in each study.
**Choice B is incorrect.** The passage explicitly says the meta-analysis found observable differences in every study, so it contradicts the assertion that mammals other than brown rats likely did not show substantial differences.
**Choice D is incorrect.** The passage makes no claim about studies'' likelihood of specifying whether effects were detrimental; it only notes that effects could be beneficial or detrimental, not reporting bias in labeling.
**Faster approach:** Restate the passage’s main claim (every study showed an effect) and eliminate choices that add unsupported comparisons or procedural claims; pick the choice that preserves the original scope and nuance.'),
  ('35012233-ddbf-5940-b0d2-d0afd06701b5', 2, null, '**Choice C is correct.** The word "since" plus the year 1945 indicates an action that began in the past and continues to the present, so Standard English requires the present perfect tense: "has collected."
**Choice A is incorrect.** "Is collecting" (present progressive) describes an action happening now but does not convey that it began in 1945 and has continued up to the present.
**Choice B is incorrect.** "Will collect" is future tense and cannot correctly be used with the past-starting time phrase "since 1945."
**Choice D is incorrect.** "Collects" (simple present) states a habitual or general truth but does not pair properly with "since 1945," which requires a perfect aspect to show continuity from a specific past time to now.
**Faster approach:** Whenever a sentence gives a specific past starting time with "since [year]," choose the present perfect (has/have + past participle).'),
  ('dbae7035-005a-58d5-b735-f1cbc5d686d2', 3, null, '**Choice D is correct.** The sentence requires the preposition "on" followed directly by the noun phrase "US currency" to complete the verb phrase "to appear on US currency." No internal punctuation is needed; a period at the end of the sentence completes it. "On" alone fits Standard English syntax and maintains the sentence’s flow.
**Choice A is incorrect.** A semicolon before "US currency" would be ungrammatical because a semicolon joins two independent clauses or separates complex list items, neither of which applies here.
**Choice B is incorrect.** A comma after "on" would create an unnecessary break between the preposition and its object, disrupting normal prepositional phrase structure.
**Choice C is incorrect.** A colon would be inappropriate because it introduces a list, explanation, or quotation; here there is simply the prepositional object "US currency," so no colon belongs.
**Faster approach:** For prepositions followed immediately by their objects, choose no internal punctuation—pick the plain preposition so the sentence reads smoothly (e.g., "on US currency").'),
  ('d8c69d7a-ac78-5a67-93c1-6e3a9718c9a7', 0, null, '**Choice A is correct.** The sentence refers to two cities named in the previous clause, so a plural demonstrative is required. "These cities" correctly matches the plural noun and implies closeness in the sentence: "In other words, these cities basically sit right on the equator!"
**Choice B is incorrect.** "That" is singular (or would require "those" for plural) and does not agree with the plural noun "cities."
**Choice C is incorrect.** "This" is singular and therefore does not agree with the plural noun "cities."
**Choice D is incorrect.** "Each" requires a singular noun ("each city") and cannot be used with the plural "cities."
**Faster approach:** Check number agreement—use a plural demonstrative ("these" or "those") when referring to multiple items named immediately before; because the items are close in the sentence, choose "these."'),
  ('34170998-6ba9-5e13-8e97-0e26d0ab26b8', 3, null, '**Choice D is correct.** The sentence states a general fact about how the phrase is rendered in English, so the simple present verb phrase "translates roughly to" is required: "In English, this phrase translates roughly to ‘it’s an old story.’" The singular subject "this phrase" agrees with the singular verb "translates," and the simple present expresses a habitual or general truth.
**Choice A is incorrect.** "to translate" is an infinitive and would create an awkward, ungrammatical construction here ("this phrase to translate roughly" is not a valid predicate).
**Choice B is incorrect.** "translating" is a present participle and would make the clause a fragment or require an auxiliary; it does not form a correct main-verb phrase for the independent clause given.
**Choice C is incorrect.** "having translated" is a perfect participle that implies a completed action and cannot serve as the simple main verb for this general-statement sentence.
**Faster approach:** For sentences stating general truths, place each choice in the blank and choose the simple present verb that agrees with the subject (subject-verb agreement test).'),
  ('9396a0d5-64fe-5680-bcff-bbae2ebc7e74', 1, null, '**Choice B is correct.** The clause "Even back in the 1860s" places the action in the past, so the verb must be in a past-tense form. "Was" correctly matches the singular noun phrase "nearly 30% of the city’s population" and the past time reference, yielding a grammatically standard sentence: "Nearly 30% of the city’s population was from outside the United States."
**Choice A is incorrect.** "Is being" is present progressive and implies an ongoing action now; it conflicts with the past time marker "back in the 1860s."
**Choice C is incorrect.** "Will be" is future tense and does not agree with the past time phrase "back in the 1860s."
**Choice D is incorrect.** "Is" is simple present tense and therefore mismatches the past reference; the sentence needs past tense.
**Faster approach:** Immediately match verb tense to the time phrase—use past tense when the sentence says something happened "back in" a past year or decade.'),
  ('510babff-4ac9-5cbe-9346-1fbd845e1696', 3, null, '**Choice D is correct.** The clause beginning with "Though" is a dependent (subordinate) clause that must be followed by a comma before the main clause. Inserting "STS-96, the" yields "Though it was designated as mission STS-96, the mission was actually the ninety-fourth flight...," which correctly links the dependent clause to the independent clause and provides the necessary comma.
**Choice A is incorrect.** "STS-96, and the" creates an unnecessary coordinating conjunction; "and" makes the sentence ungrammatical following the subordinating "Though."
**Choice B is incorrect.** "STS-96. The" creates a sentence fragment because the initial dependent clause beginning with "Though" cannot stand alone and cannot be ended with a period.
**Choice C is incorrect.** "STS-96 the" omits the required comma after the introductory subordinate clause, producing a run-on structure that violates punctuation conventions for introductory clauses.
**Faster approach:** Recognize that a clause beginning with "Though" is introductory and needs a comma before the main clause; choose the answer that supplies ", the" immediately after the designation.'),
  ('910368a4-33e9-5e18-819c-0d1de89abe4a', 0, null, '**Choice A is correct.** The sentence that follows provides a specific supporting detail about how heavy the statues are, so a transition that adds emphasis and evidence—"In fact,"—is appropriate: "Both statues are made of stone and are extremely heavy. In fact, they each weigh more than 5 tons!"
**Choice B is incorrect.** "Earlier," signals a time relationship and would be used to refer to something mentioned before, which does not fit here.
**Choice C is incorrect.** "In any case," indicates concession or irrelevance to prior conditions; it does not suit a sentence that supplies confirming detail.
**Choice D is incorrect.** "Instead," indicates contrast or substitution, but the second sentence supports rather than contrasts with the first.
**Faster approach:** Identify the relationship between sentences (support/add, contrast, time, or concession) and pick the transition that matches that relationship—here, a supporting detail needs an emphatic additive transition like "In fact."'),
  ('5e4c9413-d3fd-5213-8eab-28d9d41224c6', 3, null, '**Choice D is correct.** The sentence summarizes the sequence of trophic levels and introduces the last, highest level; the transition "Finally," signals that the author is presenting the last item in a list, so "Finally, at the fourth, highest trophic level are apex predators, like sharks, that feed on the animals below." is the most logical completion.
**Choice A is incorrect.** "In fact," indicates emphasis or correction and does not signal that this is the final item in a sequence, so it does not fit the listing context.
**Choice B is incorrect.** "Besides," adds an additional, often less important point; it does not appropriately mark the final element of a sequential list of trophic levels.
**Choice C is incorrect.** "For example," would introduce an illustration of a previous point, but the sentence is identifying the final level itself rather than giving an example of a prior claim, so it is not the best transition.
**Faster approach:** For transitions that present the last element in a sequence, pick a transition that signals conclusion or finality ("Finally,"/"Lastly,").'),
  ('6f04ef97-029c-5fa1-9b69-1809d483645c', 3, null, '**Choice D is correct.** The second sentence gives a specific detail about Smith’s job at JPL, so a transition that signals elaboration and specificity fits best. "Specifically," introduces the exact role Smith held and connects naturally to the following explanation of the Mars 2020 Perseverance rover.
**Choice A is incorrect.** "Conversely," indicates a contrast with the previous statement, but the second sentence does not present an opposing idea; it provides additional detail.
**Choice B is incorrect.** "Finally," suggests a concluding point in a series; nothing in the context indicates a list or sequence that would be ending.
**Choice C is incorrect.** "Nevertheless," implies a concession or contradiction, which doesn’t match the supportive, clarifying information that follows about Smith’s specific role.
**Faster approach:** Look for whether the next sentence adds detail, contrasts, or concludes; pick "Specifically" for elaboration, "Conversely/Nevertheless" for contrast, and "Finally" for conclusions.'),
  ('07b3977e-fbb6-558e-ba2b-6206f58cc91c', 3, null, '**Choice D is correct.** It provides a clear, concise introduction to Elizabeth Catlett by naming her as a celebrated African American artist and stating what she is best known for: creating sculptures and prints that explore the Black experience. This gives an unfamiliar audience the relevant biographical and thematic context needed to understand why Catlett is notable.
**Choice A is incorrect.** It contrasts two sculptures and their materials, but it assumes prior interest in specific works rather than introducing the artist herself; it does not summarize who Catlett is or why she matters.
**Choice B is incorrect.** It states a single fact about one sculpture (material and date) but provides no information about Catlett’s significance or typical subject matter.
**Choice C is incorrect.** It lists creation dates for two works, which may be useful detail, but it fails to introduce Catlett or explain her importance or artistic focus.
**Faster approach:** For an introduction pick the choice that gives overall identity and significance (who the person is and what they’re known for) rather than specific details about individual works.'),
  ('41cf2a1c-ec50-50f1-9422-d35e5e1e183c', 0, null, '**Choice A is correct.** The notes explicitly state that "Kaikeyi is a 2022 novel by Vaishnavi Patel" and that "The novel is a retelling of the epic poem from Kaikeyi’s point of view," so this choice directly and efficiently emphasizes whose perspective the novel presents.
**Choice B is incorrect.** It describes how Kaikeyi appears in The Ramayana (often a villain) rather than stating whose point of view the novel takes.
**Choice C is incorrect.** While the notes say the novel often portrays Kaikeyi as heroic, this choice focuses on portrayal, not on the novel’s point of view.
**Choice D is incorrect.** This only notes that The Ramayana features Kaikeyi and does not say anything about the novel’s perspective.
**Faster approach:** Scan for the phrase "from [character]’s point of view" or similar wording to identify the narrator’s perspective quickly.'),
  ('0aa00268-e11e-5556-9640-d009ea1cf18f', 2, null, '**Choice C is correct.** The notes explicitly state different specific Native elements used in each composition: "Live On, Heart of My Nation features a Choctaw hymn" and "Fantasy Aborigine No.3 incorporates a Tewa seashell rattle." Choice C directly contrasts the two works by naming the distinct elements each one uses, which most effectively emphasizes the difference between them.
**Choice A is incorrect.** It merely restates that both are compositions by Ballard and does not emphasize any difference between the two works.
**Choice B is incorrect.** Although true that Ballard blends Native traditions with Western classical music, this choice treats the two pieces similarly and does not highlight the specific difference between them.
**Choice D is incorrect.** This choice is vague: it asserts that Ballard has different approaches but does not specify the distinct elements used in each composition, so it fails to emphasize the concrete difference shown in the notes.
**Faster approach:** Look for answer choices that name the specific, contrasting details from the notes; the choice that pairs each composition with its unique detail is the correct one.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;
